<?php if($doc['kind']!=='quote')return;?>
<section class="panel padded quote-workflow"><div class="panel-heading compact"><div><h2>Suivi de la proposition</h2><p><span class="tag <?=in_array($doc['quote_state'],['Accepté','Converti'],true)?'green':'cyan'?>"><?=e(quoteLabel($doc))?></span><?php if($doc['accepted_at']):?> · Accord enregistré le <?=e(localDate($doc['accepted_at']))?><?php endif?></p></div><a class="text-link" href="<?=e(url('quotes'))?>">Tous les devis →</a></div>
<?php $draftOrigin=row('SELECT copied_from_id FROM quote_drafts WHERE issued_document_id=?',[$doc['id']]);if(!empty($draftOrigin['copied_from_id'])):$previous=row('SELECT id,number FROM documents WHERE id=?',[$draftOrigin['copied_from_id']]);?><p class="small muted">Proposition préparée depuis <a href="<?=e(url('document',['id'=>$previous['id']]))?>"><?=e($previous['number'])?></a>. La proposition précédente est conservée.</p><?php endif?>
<?php if($doc['decision_note']):?><p class="small">Référence / note : <?=e($doc['decision_note'])?></p><?php endif?>
<?php if($doc['quote_state']==='Émis'&&quoteLabel($doc)!=='Expiré'):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="quote_decision"><input type="hidden" name="id" value="<?=(int)$doc['id']?>"><input type="hidden" name="state" value="Accepté"><?php inputField('Référence de l’accord client','decision_note','','text',true,'maxlength="1000" placeholder="E-mail, bon pour accord, échange daté…"');?><label class="agreement-check"><input type="checkbox" name="agreement_confirmed" value="1" required> J’ai obtenu l’accord du client sur cette version.</label><button class="btn primary">Enregistrer l’accord client</button></form>
<details class="quote-refusal"><summary>Enregistrer un refus</summary><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="quote_decision"><input type="hidden" name="id" value="<?=(int)$doc['id']?>"><input type="hidden" name="state" value="Refusé"><?php inputField('Motif / référence du refus','decision_note','','text',true,'maxlength="1000"');?><button class="btn secondary">Enregistrer le refus</button></form></details>
<?php elseif($doc['quote_state']==='Accepté'):?><form method="post" data-confirm="Créer ou ouvrir la commande correspondant à ce devis accepté ?"><?=csrf()?><input type="hidden" name="action" value="quote_convert"><input type="hidden" name="id" value="<?=(int)$doc['id']?>"><div class="export-actions"><button class="btn primary"><?=$doc['order_id']?'Utiliser la commande existante':'Créer la commande acceptée'?> →</button></div></form>
<?php elseif($doc['quote_state']==='Converti'&&$doc['order_id']):?><div class="export-actions"><a class="btn primary" href="<?=e(url('order_form',['id'=>$doc['order_id']]))?>">Ouvrir <?=e(ref((int)$doc['order_id']))?> →</a></div><p class="small muted">Une seule commande pour ce devis. Un nouveau clic ouvre la même commande, même si elle a été annulée.</p>
<?php elseif(quoteLabel($doc)==='Expiré'):?><p class="small muted">Validité dépassée. Préparez une nouvelle proposition pour obtenir un nouvel accord.</p><?php endif?>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="quote_copy"><input type="hidden" name="id" value="<?=(int)$doc['id']?>"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="export-actions"><button class="btn secondary">Préparer une nouvelle proposition</button></div></form><p class="small muted">L’accord est enregistré par l’administrateur ; aucun message ni demande de signature n’est envoyé au client.</p></section>
